import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"风雷益","description":"周易折中 - 风雷益","frontmatter":{"title":"风雷益","description":"周易折中 - 风雷益"},"headers":[],"relativePath":"zh/classics/zhezhong/048.md","filePath":"zh/classics/zhezhong/048.md"}'),h={name:"zh/classics/zhezhong/048.md"};function n(d,a,p,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="风雷益" tabindex="-1">风雷益 <a class="header-anchor" href="#风雷益" aria-label="Permalink to “风雷益”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈益〉序卦曰：“损而不已必益，故受之以益。盛衰损益如循环，损极必益，理之自然。益所以继损也。为卦巽上震下，雷风二物相益者也。风烈则雷迅，雷激则风怒，两相助益，所以为益。此以象言也。巽震二卦皆由下变而成，阳变而为阴者损也，阴变而为阳者益也。上卦损而下卦益，损上益下，所以为益。此以义言也。下厚则上安，故益下为益。”</p><p>益：利有攸往，利涉大川</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>益，增益也。为卦损上卦初画之阳，益下卦初画之阴，自上卦而下于下卦之下，故为益卦。之九五、六二皆得中正，下震上巽，皆木之象，故其占利有所往，而利涉大川也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>益者，益于天下之道也。故利有攸往，益之道可以济险难，利涉大川也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖达曰 ：损卦则损下益上，益卦则损上益下。得名皆就下而不据上者，向秀云：“明王之道，志在惠下。”故取下谓之损，与下谓之益。</li></ul><p>孔氏颖达曰 ：损卦则损下益上，益卦则损上益下。得名皆就下而不据上者，向秀云：“明王之道，志在惠下。”故取下谓之损，与下谓之益。</p><ul><li>陆氏贽曰 ：损上益下曰益，损下益上曰损。约己而裕于人，人必悦而奉上矣，岂不谓之益乎？上蔑人而肆诸己，人必怨而畔上矣，岂不谓之损乎？</li></ul><p>陆氏贽曰 ：损上益下曰益，损下益上曰损。约己而裕于人，人必悦而奉上矣，岂不谓之益乎？上蔑人而肆诸己，人必怨而畔上矣，岂不谓之损乎？</p><ul><li>范氏仲淹曰 ：益上曰损，损上曰益者何也？益上则损下，损下则伤其本也；损上则益下，益下则固其本也。</li></ul><p>范氏仲淹曰 ：益上曰损，损上曰益者何也？益上则损下，损下则伤其本也；损上则益下，益下则固其本也。</p><ul><li>蔡氏清曰 ：损下益上，民贫则君不能独富，损道也，故为损；损上益下，民富则君不能独贫，益道也，故为益。损则上下通一，损益则上下通一益。要知关于上者为多，案彖辞与损同，亦不专主损己惠下为义。盖益以兴利，故利以图大事而济大难。天下事有动而后获益者，不可坐以需时也。</li></ul><p>蔡氏清曰 ：损下益上，民贫则君不能独富，损道也，故为损；损上益下，民富则君不能独贫，益道也，故为益。损则上下通一，损益则上下通一益。要知关于上者为多，案彖辞与损同，亦不专主损己惠下为义。盖益以兴利，故利以图大事而济大难。天下事有动而后获益者，不可坐以需时也。</p><p>象曰：风雷益，君子以见善则迁，有过则改</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>风雷之势，交相助益。迁善改过，益之大者，而其相益亦犹是也。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>风烈则雷迅，雷激则风怒，二物相益者也。君子观风雷相益之象，而求益于己。为益之道无若见善则迁，有过则改也。见善能迁，则可以尽天下之善；有过能改，则无过矣。益于人者，无大于是。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：迁善改过，益莫大焉。</p></li><li><p>胡氏炳文曰：雷与风自有相益之势，速于迁善则过当益寡，决于改过则善当益纯。是迁善改过，又自有相益之功也。</p></li><li><p>蒋氏悌生曰：风雷相益，迅速不迟。君子法之，见善则即迁，知过必速改，不可犹豫。</p></li><li><p>何氏楷曰：咸言速，心之德通于虚也。不损不虚，惩忿窒欲，损之又损，致虚以复其为咸。恒言久，心之德凝于实也。不益不实，迁善改过，益之又益，充实而成其为恒。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>雷者动阳气者也，故人心奋发而勇于善者如之。风者散阴气者也，故人心荡涤以消其恶者如之。</p><p>彖曰：益，损上益下，民说无疆，自上下下，其道大光</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>以卦义与卦才言也。卦之为益，以其损上益下也。损于上而益下，则民说之无疆，为无穷极也。自上而降己以下下，其道之大光显也。阳下居初，阴上居四，为自上下下之义。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：损其道上行（以上两句皆释损义）；益其道大光（以上四句皆释益义）。</li></ul><p>利有攸往，中正有庆，利涉大川，木道乃行</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦体卦象释卦辞。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>五以刚阳中正居尊位，二复以中正应之，是以中正之道益天下，天下受其福庆也。益之为道，于平常无事之际，其益犹小；当艰危险难，则所益至大，故利涉大川也。于济艰险，乃益道大行之时也。益误作木，或以为上巽下震，故云木道，非也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱氏震曰 ：利涉大川言木者三，益也、涣也、中孚也，皆巽也。</li></ul><p>益动而巽，日进无疆，天施地生，其益无方，凡益之道，与时偕行</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>动、巽二卦之德，干下施，坤上生，亦上文卦体之义，又以此极言赞益之大。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>又以二体言卦才。下动而上巽，动而巽也，为益之道。其动巽顺于理，则其益日进广大，无有疆限也。动而不顺于理，岂能成大益也？以天地之功言益道之大，圣人体之以益天下也。天道资始，地道生物，天施地生，化育万物，各正性命，其益可谓无方矣。方所也，有方所则有限量，无方谓广大无穷极也。天地之益万物，岂有穷际乎？天地之益无穷者，理而已矣。圣人利益天下之道，应时顺理，与天地合，与时偕行也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>顾氏象德曰 ：既奋发又沈潜，学所以日新，故日进无疆。天下施，地上行，化所以不已，故其益无方。此皆时之自然者，故曰凡益之道，与时偕行。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>动巽取卦德，施生取卦象。风者天施也，故姤有施命之象；雷者地生也，故解有甲拆之象。损之与时偕行者，时当损而损也；益之与时偕行者，时当益而益也。人事也，造化也，非气候之至则不能强为益也。</p><p>初九：利用为大作，元吉无咎</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>初虽居下，然当益下之时，受上之益者，也不可徒然无所报效，故利用为大作，必元吉然后得无咎。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>初九，震动之主，刚阳之盛也。居益之时，其才足以益物。虽居至下，而上有六四之大臣应于己。四巽顺之主，上能巽于君，下能顺于贤才也。在下者不能有为，得在上者应从之，则宜以其道辅于上，作大益天下之事，利用为大作也。居下而得上之用，以行其志，必须所为大善而吉，则无过咎。不能元吉，则不惟在已有咎，乃累乎上，为上之咎也。在至下而当大任，小善不足以称也，故必元吉然后得无咎。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱子语类云 ：初九在下，为四所任，而大作者必尽善而后无咎，若所作不尽善，未免有咎也。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>卦以损四益初为义，则初亦受益之极，卦之主也，故其辞亦与卦同。“利用为大作”者，即彖所谓“利有攸往，利涉大川”也。必大为益人之事，然后可以自受其益，非然，则受大益者乃所以为大损矣。凡《易》中言“吉无咎”者，皆谓得吉而后可以免咎，而损彖辞及此爻与萃四之辞为尤著。</p><p>象曰：元吉无咎，下不厚事也</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>下本不当任厚事，故不如是不足以塞咎也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>在下者本不当处厚事（厚事，重大之事也），以为在上所任。所以当大事必能济大事而致元吉，乃为无咎。能致元吉，则在上者任之为知人，已当之为胜任。不然，则上下皆有咎也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏汝谐曰：得益者非以是而自私也，故损之上利有攸往。得臣无家，益之初利用为大作。为大作者，当为大益之事也。然在下而为大益之事，位未崇也，诚未孚也。必元吉然后无咎，以其位非厚事之地也。</p></li><li><p>朱子语类云：“利用大作”象曰“下不厚事也”，自此推之，则凡居下者不当厚事，如子之于父，臣之于君，僚属之于官长，皆不可以逾分越职。纵可为，亦须是尽善，方能无过。所以有“元吉无咎”之戒也。</p></li></ul><p>六二：或益之十朋之龟，弗克违，永贞吉。王用享于帝，吉</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>六二当益下之时，虚中处下，故其象占与损六五同。然爻位皆阴，故以“永贞”为戒。以其居下而受上之益，故又为卜郊之吉占。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>六二处中正而体柔顺，有虚中之象。人处中正之道，虚其中以求益，而能顺从，天下孰不愿告而益之？孟子曰：“夫苟好善，则四海之内皆将轻千里而来告之以善。”夫满则不受，虚则来，物理自然也。故或有可益之事，则众朋助而益之。十者众辞，众人所是，理之至当也。龟者占吉凶、辨是非之物，言其至是，龟不能违也。永贞吉，就六二之才而言，二中正虚中，能得众人之益者也。然而质本阴柔，故戒在常永贞固，则吉也。求益之道，非永贞则安能守也。损之六五，“十朋之龟”则元吉者，盖居尊自损，应下之刚，以柔而居刚，柔为虚受，刚为固守，求益之至善，故元吉也。六二虚中求益，亦有刚阳之应，而以柔居柔，疑益之未固也，故戒能常永贞固，则吉也。王用享于帝，吉。如二之虚中而能永贞，用以享上帝，犹当吉，况与人接物，其意有不通乎？求益于人有不应乎？祭天，天子之事，故云“王用”也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏逢曰 ：为臣若是，王者用之可享上帝。</li></ul><p>王氏逢曰 ：为臣若是，王者用之可享上帝。</p><ul><li>郭氏雍曰 ：或益之者，人益之也；十朋之龟弗克违，鬼神益之也；王用享于帝吉，天益之也。天且弗违，况于人与鬼神乎？</li></ul><p>郭氏雍曰 ：或益之者，人益之也；十朋之龟弗克违，鬼神益之也；王用享于帝吉，天益之也。天且弗违，况于人与鬼神乎？</p><ul><li>兰氏廷瑞曰 ：六二柔顺，受益之臣，王用之可以享帝获吉，如成汤用伊尹而享天心，太戊用伊陟而格上帝。</li></ul><p>兰氏廷瑞曰 ：六二柔顺，受益之臣，王用之可以享帝获吉，如成汤用伊尹而享天心，太戊用伊陟而格上帝。</p><ul><li>李氏简曰 ：王用享于帝吉，犹言使之主祭而百神享之也。</li></ul><p>李氏简曰 ：王用享于帝吉，犹言使之主祭而百神享之也。</p><ul><li>郑氏维岳曰 ：王用享帝，言王用六二以享帝也。古人一德克享天心，又曰吁俊尊上帝。</li></ul><p>郑氏维岳曰 ：王用享帝，言王用六二以享帝也。古人一德克享天心，又曰吁俊尊上帝。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>郭氏之说于文意甚明。益之者人也，弗克违者鬼神也。然必克当天心，乃获是应。故损五象传推本于自上祐，而此爻辞又更有享于上帝之义也。郑氏谓“王用六二以享帝”者极是。随上升四其义皆同，但彼云西山、岐山，而此云上帝者，彼但言鬼神享之而已。此爻上文既云“朋龟弗违”，则鬼神其依之义已见，故复推而上之至于上帝。若山川之神，则不大于蓍龟也。</p><p>象曰：或益之，自外来也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>或者众无定主之辞。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>既中正虚中，能受天下之善而固守，则有有益之事，众人自外来益之矣。或曰自外来，岂非谓五乎？曰：如二之中正虚中，天下孰不愿益之？五为正应，固在其中矣。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：自外来者，明益之者从外而来，不召而至也。</p></li><li><p>杨氏简曰：或益之自外来也，亦犹损六五之“或益之自上祐也”，皆言本无求益之意，而益自至也。曰“自外来”，言非中心之所期，自外而至也。</p></li></ul><p>六三：益之用凶事，无咎，有孚中行，告公用圭</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>六三阴柔，不中不正，不当得益者也。然当益下之时，居下之上，故有益之以凶事者，盖警戒震动乃所以益之也。占者如此，然后可以无咎。又戒以有孚中行而告公用圭。用圭所以通信。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>三居下体之上，在民上者也，乃守令也。居阳应刚，处动之极，居民上而刚决果于为益者也。果于为益，用之凶事，则无咎。凶事谓患难非常之事。三居下之上，在下当承禀于上，安得自任擅为益乎？唯于患难非常之事，则可量宜应卒，奋不顾身力庇其民，故无咎也。下专自任，上必忌疾。虽当凶难以义在可为，然必有其孚诚，而所为合于中道，则诚意通于上，而上信与之矣。专为而无为，上爱民之至诚固不可也。虽有诚意而所为不合中行，亦不可也。圭者，通信之物。《礼》云：“大夫执圭而使”，所以申信也。凡祭祀、朝聘用圭玉，所以通达诚信。有诚孚而得中道，则能使上信之，是犹告公用圭玉也。其孚能通逹于上矣。在下而有为之道，固当有孚中行。又三阴爻而不中，故发此义。或曰：“三乃阴柔，何得反以刚众任事为义？”曰：“三质虽本阴，然其居阳，乃自处以刚也。应刚，乃志在乎刚也。居动之极，刚果于行也。以此行益，非刚果而何？易以所胜为义，故不论其本质也。”</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏安石曰 ：以至诚而中行，则不独无咎，可以成功。圭者，所以告成功也。</li></ul><p>王氏安石曰 ：以至诚而中行，则不独无咎，可以成功。圭者，所以告成功也。</p><ul><li>游氏酢曰 ：益则吉矣，而用凶事者，所谓吉人凶其吉也。三居下体之上，当震之极，不用凶事，则高而危，满而溢矣。</li></ul><p>游氏酢曰 ：益则吉矣，而用凶事者，所谓吉人凶其吉也。三居下体之上，当震之极，不用凶事，则高而危，满而溢矣。</p><ul><li>朱子语类云 ：益之用凶事，犹书言“用降我凶德嘉绩于朕邦”。</li></ul><p>朱子语类云 ：益之用凶事，犹书言“用降我凶德嘉绩于朕邦”。</p><ul><li>蔡氏渊曰 ：凶事困心衡虑之事，在一卦之中，故三四皆曰“中行”。</li></ul><p>蔡氏渊曰 ：凶事困心衡虑之事，在一卦之中，故三四皆曰“中行”。</p><ul><li>蔡氏清曰 ：当益之时，概当得益。而居下之上，乃危地也，故独为益之以凶事之象。虽益之而以凶事，虽凶事亦益之也。所谓“苦其心志，行拂乱其所为，所以动心忍性，增益其所不能者也”。其功夫又在有孚中行上。</li></ul><p>蔡氏清曰 ：当益之时，概当得益。而居下之上，乃危地也，故独为益之以凶事之象。虽益之而以凶事，虽凶事亦益之也。所谓“苦其心志，行拂乱其所为，所以动心忍性，增益其所不能者也”。其功夫又在有孚中行上。</p><ul><li>张氏振渊曰 ：益不以美事而以凶事，如投之艰难，寘之盘错，儆戒震动之谓也。无咎，言可因是而迁善补过也。下二句正言其所以无咎，有孚者涤虑洗心，诚于体国而不欺；中行者履正奉公，合于中道而不悖。即此便是上通于君，处犹告公而用圭以通信者然。案此爻与损之六四相反对，损四受下之益者，此爻受上之益者。然皆不言所益而曰疾曰凶事，盖三四凶惧之位也，故其获益亦与他爻不同。在上位者而知损四之义，则不以下之承奉为益，而能匡其过，能辅其所不逮者，乃益也。在下位者而知此爻之义，则不以上之恩荣为益，而试之诸艰，投之以多难者，乃益也。然在损四则宜速以改过，在此爻则宜缓以通诚，乃有以为受益之地。</li></ul><p>张氏振渊曰 ：益不以美事而以凶事，如投之艰难，寘之盘错，儆戒震动之谓也。无咎，言可因是而迁善补过也。下二句正言其所以无咎，有孚者涤虑洗心，诚于体国而不欺；中行者履正奉公，合于中道而不悖。即此便是上通于君，处犹告公而用圭以通信者然。案此爻与损之六四相反对，损四受下之益者，此爻受上之益者。然皆不言所益而曰疾曰凶事，盖三四凶惧之位也，故其获益亦与他爻不同。在上位者而知损四之义，则不以下之承奉为益，而能匡其过，能辅其所不逮者，乃益也。在下位者而知此爻之义，则不以上之恩荣为益，而试之诸艰，投之以多难者，乃益也。然在损四则宜速以改过，在此爻则宜缓以通诚，乃有以为受益之地。</p><p>象曰：益用凶事，固有之也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>益用凶事，欲其困心衡虑而固有之也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>六三益之，独可用于凶事者，以其固有之也。谓专固自任其事也。居下当禀承于上，乃专任其事，唯救民之凶灾，拯时之艰急则可也。乃处急难变故之权宜，故得无咎。若平时则不可也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>龚氏焕曰：益之以凶事，虽曰灾自外来，而已乃受益，乃其已分之所固有者，非自外来也。</li></ul><p>六四：中行，告公从，利用为依迁国</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>三四皆不得中，故皆以中行为戒。此言以益下为心而合于中行，则告公而见从矣。传曰：“周之东迁，晋郑焉依。”盖古者迁国以益下，必有所依然后能立。此爻又为迁国之吉占也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>四当益时，处近君之位，居得其正，以柔巽辅上，而下顺应于初之刚阳，如是可以益于上也。唯处不得其中，而所应又不中，是不足于中也。故云：“若行得中道，则可以益于君上，告于上而获信从矣。”以柔巽之体，非有刚特之操，故利用为依。迁国为依，依附于上也。迁国顺下而动也，上依刚中之君而致其益，下顺刚阳之才以行其事，利用如是也。自古国邑民不安其居，则迁。迁国者，顺下而动也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏曰愼曰 ：四正主于益下者，然非君位，不敢自专，必告于公也。中行则见从矣。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>此爻亦与损三相反对。损三为卦之所损以益上者，此爻为卦之所损以益下者，故辞义相类。损三无私交而与上同德，乃可以益上；此爻不专己而与上同德，乃可以益下也。用“利用”六四，也与六二“王用”之用同。迁国大事也，亦即卦之所谓“利有攸往，利涉大川”者也。</p><p>象曰：告公从，以益志也</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>爻辞但云“得中行则告公而获从”，象复明之曰“告公而获从者”，告之以益天下之志也。志苟在于益天下，上必信而从之。事君者不患上之不从，患其志之不诚也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>龚氏焕曰：六四之告公，以益民为志，故得见从也。</li></ul><p>九五：有孚惠心，勿问元吉，有孚惠我德</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>上有信以惠于下，则下亦有信以惠于上矣。不问而元吉可知。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>五刚阳中正，居尊位，又得六二之中正相应，以行其益，何所不利？以阳实在中，有孚之象也。以九五之德、之才、之位，而中心至诚在惠益于物，其至善大吉，不问可知，故云“勿问元吉”。人君居得致之位，操可致之权，苟至诚益于天下，天下受其大福，其元吉不假言也。“有孚惠我德”，人君至诚益于天下，天下之人无不至诚爱戴，以君之德泽为恩惠也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰 ：得位履尊，为益之主者也。为益之大，莫大于信；为惠之大，莫大于心。因民所利而利之，焉惠而不费，惠心者也。信以惠心，尽物之愿，固不待问而元吉。以诚惠物，物亦应之，故曰“有孚惠我德”也。</li></ul><p>王氏弼曰 ：得位履尊，为益之主者也。为益之大，莫大于信；为惠之大，莫大于心。因民所利而利之，焉惠而不费，惠心者也。信以惠心，尽物之愿，固不待问而元吉。以诚惠物，物亦应之，故曰“有孚惠我德”也。</p><ul><li>吕氏祖谦曰 ：人君但诚心惠民，不须问民之感。如此，然后元吉。民皆交孚而惠君之德。苟惠民而先问民之感不感，是计功利，非诚心惠民者也，安能使民之乐应乎？</li></ul><p>吕氏祖谦曰 ：人君但诚心惠民，不须问民之感。如此，然后元吉。民皆交孚而惠君之德。苟惠民而先问民之感不感，是计功利，非诚心惠民者也，安能使民之乐应乎？</p><ul><li>蔡氏清曰 ：惠心，惠下之心也；惠我德，下惠我之德也。而皆有孚，上感而下应也。有孚之施于下者，在我只为心；自下之受此施者，目之则为德矣。实非有二也。</li></ul><p>蔡氏清曰 ：惠心，惠下之心也；惠我德，下惠我之德也。而皆有孚，上感而下应也。有孚之施于下者，在我只为心；自下之受此施者，目之则为德矣。实非有二也。</p><ul><li>郑氏维岳曰 ：损之六五受下之益者也，益之九五益下者也。损六五受益而获元吉，益九五但知民之当益而已，勿问元吉也。此惠心之出于有孚者也。然上虽不望德于民，而民固德其惠矣。其德其惠，亦出于有孚也。故曰“王道本于诚意”。</li></ul><p>郑氏维岳曰 ：损之六五受下之益者也，益之九五益下者也。损六五受益而获元吉，益九五但知民之当益而已，勿问元吉也。此惠心之出于有孚者也。然上虽不望德于民，而民固德其惠矣。其德其惠，亦出于有孚也。故曰“王道本于诚意”。</p><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>“勿问”二字，吕氏说是，观孔子《象传》可见。</p><p>象曰：有孚惠心，勿问之矣；惠我德，大得志也</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>人君有至诚惠益天下之心，其元吉不假言也，故云“勿问之矣”。天下至诚懐吾德以为惠，是其道大行，人君之志得矣。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>崔氏憬曰：损上之时，一以损己为念，虽有孚惠心及下，终不言以彰已功，故曰“有孚惠心勿问”。问犹言也。如是获元吉，且为下所信而懐己德，故曰“有孚惠我德”。君虽不言，人惠其徳，则我大得志也。</p></li><li><p>张氏振渊曰：惠出于心，又何问焉？大得志非以民之惠我为得志，以我足以致民惠我为得志也。</p></li></ul><p>上九：莫益之，或击之，立心勿恒，凶</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>以阳居益之极，求益不已，故莫益而或击之。立心勿恒，戒之也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>上居无位之地，非行益于人者也。以刚处益之极，求益之甚者也。所应者阴，非取善自益者也。利者，众人所同欲也。专欲益己，其害大矣。欲之甚，则昏蔽而忘义理；求之极，则侵夺而致仇怨。故夫子曰：“放于利而行，多怨。”孟子谓“先利则不夺不餍”。圣贤之深戒也。九以刚而求益之极，众人所共恶，故无益之者而或攻击之矣。立心勿恒，凶。圣人戒人存心不可专利，云“勿恒”，如是凶之道也，所当速改也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖达曰 ：上九处益之极，益之过甚者也。求益无厌，怨者非一，故曰“莫益之，或击之”也。“勿”犹无也，求益无已，是立心无恒者也。无恒之人，必凶咎之所集。</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>卦义损上益下，则上者受损之极者也。若以受损为克己利下，亦可；而爻义不然者，盖能克己利下，则受益莫大焉，不得云受损矣。故损上以处损之终，自损之极而得益为义；此爻以处益之终，自益之极而得损为义。《书》云：“满招损，谦受益。”两爻之意相备也。</p><p>象曰：莫益之，偏辞也；或击之，自外来也</p><h3 id="本义-14" tabindex="-1">本义 <a class="header-anchor" href="#本义-14" aria-label="Permalink to “本义”">​</a></h3><p>莫益之者，犹从其求益之偏辞而言也。若究而言之，则又有击之者矣。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>理者天下之至公，利者众人所同欲。苟公其心，不失其正理，则与众同利，无侵于人，人亦欲与之。若切于好利，蔽于自私，求自益以损于人，则人亦与之力争，故莫肯益之而有击夺之者矣。云“莫益之者”，非其偏己之辞也。苟不偏己，合于公道，则人亦益之，何为击之乎？既求益于人至于甚极，则人皆恶而欲攻之，故击之者自外来也。人为善，则千里之外应之，六二中正虚己，益之者自外而至是也。苟为不善，则千里之外违之，上九求益之极，击之者自外而至是也。《系辞》曰：“君子安其身而后动，易其心而后语，定其交而后求。”君子脩此三者，故全也。危以动则民不与也，惧以语则民不应也，无交而求则民不与也。莫之与，则伤之者至矣。《易》曰：“莫益之，或击之。”立心勿恒，凶。君子言、动与求皆以其道，乃完善也。不然，则取伤而凶矣。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：二不求益而或益之自外来也，上求益而或击之亦自外来也。孰有以来之？五之吉，由中心之有孚；上之凶，由立心之勿恒。吉凶之道，未有不自心生者。</li></ul><p>总论</p><ul><li>熊氏良辅曰 ：损益二卦，皆以损阳益阴为义。损自泰来者也，益自否来者也。天下之理，未有泰而不否，否而不泰，亦未有损而不益，益而不损者。故泰居上经十一卦而损居下经十一卦，泰否损益为上下经之对，后天序易，其微意盖可识矣。</li></ul>',168)])])}const u=l(h,[["render",n]]);export{b as __pageData,u as default};
